import re
from itertools import permutations, combinations
import time
import json

class Fact:
    def __init__(self, predicate, args):
        self.predicate = predicate
        self.args = tuple(args)
    def __eq__(self, other):
        return self.predicate == other.predicate and self.args == other.args
    def __hash__(self):
        return hash((self.predicate, self.args))
    def __repr__(self):
        return f"{self.predicate}({', '.join(self.args)})"

def parse_rule(rule_str):
    ant_str, cons_str = rule_str.split('=>')
    ants = [a.strip().split() for a in ant_str.split(',')]
    cons = [c.strip().split() for c in cons_str.split(',')]
    return ants, cons

def load_rules(filepath):
    rules = []
    with open(filepath, 'r') as f:
        for line in f:
            if '=>' in line:
                rules.append(parse_rule(line.strip()))
    return rules

def match_pattern(pattern, fact, mapping):
    if pattern[0] != fact.predicate:
        return False
    if len(pattern) - 1 != len(fact.args):
        return False
    new_mapping = mapping.copy()
    for p_arg, f_arg in zip(pattern[1:], fact.args):
        if p_arg.isupper() or p_arg.islower(): # Variable
            if p_arg in new_mapping:
                if new_mapping[p_arg] != f_arg:
                    return False
            else:
                new_mapping[p_arg] = f_arg
        else:
            if p_arg != f_arg:
                return False
    return new_mapping

def match_antecedents(antecedents, facts, current_mapping, index=0):
    if index == len(antecedents):
        yield current_mapping
        return

    ant = antecedents[index]
    for fact in facts:
        new_mapping = match_pattern(ant, fact, current_mapping)
        if new_mapping is not False:
            yield from match_antecedents(antecedents, facts, new_mapping, index + 1)

def apply_rules(facts, rules):
    new_facts = set()
    for ants, cons in rules:
        for mapping in match_antecedents(ants, facts, {}):
            for c in cons:
                pred = c[0]
                args = [mapping.get(arg, arg) for arg in c[1:]]
                new_fact = Fact(pred, args)
                if new_fact not in facts:
                    new_facts.add(new_fact)
    return new_facts

def parse_initial_facts(premises):
    facts = set()
    for p in premises:
        # e.g., 'a b = segment a b'
        # e.g., 'g1 = on_tline g1 a a b'
        # e.g., 'm = on_circle m g1 a, on_circle m g2 b'
        parts = p.split('=')
        if len(parts) == 2:
            entities = parts[0].strip().split()
            assignments = parts[1].strip().split(',')
            for assignment in assignments:
                tokens = assignment.strip().split()
                if len(tokens) > 0:
                    pred = tokens[0]
                    args = tokens[1:]
                    facts.add(Fact(pred, args))
    return set(facts)

def parse_goal(goal_str):
    tokens = goal_str.strip().split()
    return Fact(tokens[0], tokens[1:])

def solve(problem, rules, max_depth=3, timeout=5):
    facts = parse_initial_facts(problem['premises'])
    goal = parse_goal(problem['goal'])

    start_time = time.time()
    for depth in range(max_depth):
        if time.time() - start_time > timeout:
            return False, depth, len(facts), time.time() - start_time

        if goal in facts:
            return True, depth, len(facts), time.time() - start_time

        new_facts = apply_rules(facts, rules)
        if not new_facts:
            break
        facts.update(new_facts)

    if goal in facts:
        return True, max_depth, len(facts), time.time() - start_time
    return False, max_depth, len(facts), time.time() - start_time

if __name__ == '__main__':
    from proof_generator import read_problems
    problems = read_problems('data/imo_ag_30.txt')
    rules = load_rules('data/rules.txt')

    results = []
    print(f"Solving {len(problems)} problems...")
    for i, prob in enumerate(problems):
        success, depth, num_facts, t = solve(prob, rules, max_depth=3, timeout=2)
        print(f"[{i+1}/{len(problems)}] {prob['name']}: {'Success' if success else 'Failed'} (Facts: {num_facts}, Time: {t:.2f}s)")
        results.append({
            'name': prob['name'],
            'success': success,
            'depth': depth,
            'num_facts': num_facts,
            'time': t
        })

    with open('outputs/symbolic_results.json', 'w') as f:
        json.dump(results, f, indent=2)
